public function check() {
  $values = $this->request->getValues();
  if (REMEMBER_ME_AUTH) { session_set('hasRememberMe', ! empty($values['remember_me'])); }
  list($valid, $errors) = $this->authValidator->validateForm($values);
  if ($valid) { $this->redirectAfterLogin(); } else { $this->login($values, $errors); }
}

public function logout() {
  if (! DISABLE_LOGOUT) {
    $this->checkCSRFParam();
    $this->sessionManager->close();
    $this->response->redirect($this->helper->url->to('AuthController', 'login'));
  } else { $this->response->redirect($this->helper->url->to('DashboardController', 'show')); }
}

